namespace BuildSystem.Tests;

/// <summary>
/// Settings with <see cref="global::System.Collections.Generic.IDictionary{TKey, TValue}"/> type that 
/// are generated by <see cref="global::BuildSystem.Tests.ProjectCollectionExtension.GetDefaultProjectCollectionSettings(BuildSystem.Tests.ProjectCollectionSettings)"/> and  
/// it will be used for <see cref="global::Microsoft.Build.Evaluation.ProjectCollection"/> 
/// </summary>
public record class ProjectCollectionSettings
{
    /// <summary>
    /// see `ManagePackageVersionsCentrally` key-value pair of <see cref="global::BuildSystem.Tests.ProjectCollectionExtension.GetDefaultProjectCollectionSettings(ProjectCollectionSettings)"/>
    /// </summary>
    public bool? ManagePackageVersionsCentrally { get; init; } = null;
    /// see `DirectoryPackagesPropsPath` key-value pair of <see cref="global::BuildSystem.Tests.ProjectCollectionExtension.GetDefaultProjectCollectionSettings(ProjectCollectionSettings)"/>
    public string? DirectoryPackagesPropsPath { get; init; }
    /// determine to add `ImportDirectoryBuildProps` key-value pair with value of false in 
    /// <see cref="global::BuildSystem.Tests.ProjectCollectionExtension.GetDefaultProjectCollectionSettings(ProjectCollectionSettings)"/> method to 
    /// let msbuild not recursively search `Directory.Build.props` from down to top when 
    /// one or more of global configurations files (e.g. `Directory.Build.props`) are found and
    /// Similarly, add `ImportDirectoryBuildTargets` key-value pair with value false.
    public bool ShouldStopRecursivelySearchWhenFound { get; init; }
}
